#include <stdio.h>

/* menuDoDia le o numero do dia digitado e imprime o prato do dia:
   1 sopa · 2 arroz com feijao · 3 macarrao · 4 peixe · 5 pizza
   6 churrasco · 7 lasanha · qualquer outro: dia invalido
   O primeiro botao do painel ja esta escrito — continue os outros. */
void menuDoDia(void) {
    int dia = 0;
    scanf("%d", &dia);

    switch (dia) {
        case 1:
            printf("sopa\n");
            break;
        /* continue daqui: case 2 ate case 7, cada um com o seu break,
           e o default com "dia invalido" no fim */
    }
}

