#include <stdio.h>

/* teste do desafio menu-do-dia — counter_protocol (03-tdd 3.9.3).
   O main e o relatorio sao do harness; aqui so existem cenarios SM_TEST.
   Cada cenario escreve num arquivo o dia que a pessoa "digitaria", aponta
   o stdin para esse arquivo (freopen) e captura o stdout no proprio teste.
   Os arquivos temporarios sao POR CENARIO: um cenario nunca le a entrada
   nem a captura do outro. Nunca ha fclose de stdin/stdout — so fflush —
   para o freopen seguinte ficar legal (C11 7.21.4). */

/* prototipo da funcao do aluno (o teste declara o que exercita) */
void menuDoDia(void);

SM_TEST(o_dia_1_e_sopa) {
    FILE *e = fopen("sm_entrada_1.tmp", "w");
    fprintf(e, "1\n");
    fclose(e);
    freopen("sm_entrada_1.tmp", "r", stdin);

    freopen("sm_saida_1.tmp", "w", stdout);
    menuDoDia();
    fflush(stdout);

    FILE *f = fopen("sm_saida_1.tmp", "r");
    char linha[80] = "(nada impresso)";
    fgets(linha, 80, f);
    checa_str("o dia 1 e sopa", linha, "sopa\n",
              "o 1 entra pelo case 1 do painel");
    /* a PROVA do break: sem ele a execucao cai no case de baixo e uma
       segunda linha aparece aqui */
    char fim[80] = "(nada impresso)";
    fgets(fim, 80, f);
    checa_str("nao ha prato a mais", fim, "(nada impresso)",
              "o break fecha o caso: um dia, um prato, uma linha");
    fclose(f);
}

SM_TEST(o_dia_6_e_churrasco) {
    FILE *e = fopen("sm_entrada_2.tmp", "w");
    fprintf(e, "6\n");
    fclose(e);
    freopen("sm_entrada_2.tmp", "r", stdin);

    freopen("sm_saida_2.tmp", "w", stdout);
    menuDoDia();
    fflush(stdout);

    FILE *f = fopen("sm_saida_2.tmp", "r");
    char linha[80] = "(nada impresso)";
    fgets(linha, 80, f);
    checa_str("o dia 6 e churrasco", linha, "churrasco\n",
              "o 6 salta direto para o case 6, sem passar pelos de cima");
    char fim[80] = "(nada impresso)";
    fgets(fim, 80, f);
    checa_str("nao ha prato a mais no dia 6", fim, "(nada impresso)",
              "o break do case 6 impede a queda para o case 7");
    fclose(f);
}

SM_TEST(o_dia_9_e_invalido) {
    FILE *e = fopen("sm_entrada_3.tmp", "w");
    fprintf(e, "9\n");
    fclose(e);
    freopen("sm_entrada_3.tmp", "r", stdin);

    freopen("sm_saida_3.tmp", "w", stdout);
    menuDoDia();
    fflush(stdout);

    FILE *f = fopen("sm_saida_3.tmp", "r");
    char linha[80] = "(nada impresso)";
    fgets(linha, 80, f);
    checa_str("o dia 9 nao tem botao", linha, "dia invalido\n",
