#include <stdio.h>

void menuDoDia(void) {
    int dia = 0;
    scanf("%d", &dia);

    switch (dia) {
        case 1:
            printf("sopa\n");
            break;
        case 2:
            printf("arroz com feijao\n");
            break;
        case 3:
            printf("macarrao\n");
            break;
        case 4:
            printf("peixe\n");
            break;
        case 5:
            printf("pizza\n");
            break;
        case 6:
            printf("churrasco\n");
            break;
        case 7:
            printf("lasanha\n");
            break;
        default:
            printf("dia invalido\n");
            break;
    }
}
